mapper.select:
SELECT li.tenant_id AS tenantId, t.tenant_code AS tenantCode, li.login_code AS id, u.user_nm AS name, li.password_hash AS password, NULL AS ihidNum, u.email_adres AS email, CASE WHEN r.role_code = 'PLATFORM_ADMIN' THEN 'ADM' ELSE 'USR' END AS userSe, u.department_id AS orgnztId, u.user_id::text AS uniqId, u.department_id AS groupId, COALESCE(d.department_nm, u.department_id::text) AS groupCode, CASE WHEN r.role_code = 'PLATFORM_ADMIN' THEN 'ROLE_ADMIN' WHEN r.role_code = 'TENANT_ADMIN' THEN 'ROLE_TENANT_ADMIN' ELSE 'ROLE_USER' END AS groupNm, r.role_code AS roleCode FROM tb_login_account li JOIN tb_user u ON u.login_id = li.login_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id JOIN tb_login_account_role lr ON lr.login_id = li.login_id JOIN tb_role r ON r.role_id = lr.role_id LEFT JOIN tb_department d ON d.department_id = u.department_id WHERE li.login_code = #{id} AND li.password_hash = #{password} AND li.tenant_id = #{tenantId}
AND r.role_code = #{roleCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(d.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y' AND COALESCE(r.use_at, 'Y') = 'Y'

SELECT li.login_code AS id FROM tb_login_account li JOIN tb_user u ON u.login_id = li.login_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id WHERE u.user_nm = #{name} AND u.email_adres = #{email}
AND t.tenant_code = #{tenantCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y' ORDER BY li.created_at DESC LIMIT 1

SELECT li.password_hash AS password FROM tb_login_account li JOIN tb_user u ON u.login_id = li.login_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id WHERE li.login_code = #{id} AND u.user_nm = #{name} AND u.email_adres = #{email}
AND t.tenant_code = #{tenantCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y'
